<span class="line"><span style="color:#85E89D;">      command</span><span style="color:#E1E4E8;">: [ </span><span style="color:#9ECBFF;">&quot;/bin/sh&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;-c&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;ls /etc/config/&quot;</span><span style="color:#E1E4E8;"> ]</span></span>
